function StatCard({ icon, value, label, unit = '', isDark }) { return (<div className={`rounded-xl shadow-sm border p-2 sm:p-3 text-center flex flex-col justify-center h-full transition-colors ${isDark?'bg-gray-800 border-gray-700':'bg-white border-gray-100'}`}><div className="mb-1 flex justify-center" aria-hidden="true">{icon}</div><p className={`text-lg sm:text-xl font-bold truncate ${isDark?'text-white':'text-gray-900'}`}>{value}{unit}</p><p className={`text-[10px] sm:text-xs truncate ${isDark?'text-gray-400':'text-gray-500'}`}>{label}</p></div>); }
function ResultCard({ label, value, unit = '', icon, color, isDark }) { const colorMap = { blue:{bg:'bg-blue-500/10',border:'border-blue-500/30',text:'text-blue-500',icon:'text-blue-500'}, yellow:{bg:'bg-yellow-500/10',border:'border-yellow-500/30',text:'text-yellow-500',icon:'text-yellow-500'}, green:{bg:'bg-green-500/10',border:'border-green-500/30',text:'text-green-500',icon:'text-green-500'}, emerald:{bg:'bg-emerald-500/10',border:'border-emerald-500/30',text:'text-emerald-500',icon:'text-emerald-500'}, cyan:{bg:'bg-cyan-500/10',border:'border-cyan-500/30',text:'text-cyan-500',icon:'text-cyan-500'}, purple:{bg:'bg-purple-500/10',border:'border-purple-500/30',text:'text-purple-500',icon:'text-purple-500'} }; const c=colorMap[color]||colorMap.blue; return (<div className={`flex items-center justify-between p-3 rounded-lg border ${c.bg} ${c.border}`}><div className="flex items-center gap-2 min-w-0"><div className={c.icon} aria-hidden="true">{icon}</div><span className={`text-xs sm:text-sm truncate ${isDark?'text-gray-300':'text-gray-600'}`}>{label}</span></div><span className={`font-bold text-base sm:text-lg flex-shrink-0 ml-2 ${c.text}`}>{value}{unit}</span></div>); }